<script setup lang="ts">
import {usePayrollReturn} from '../payrollReturn'
const payrollReturn=usePayrollReturn()
import {computed,onMounted,reactive,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {usePayrollPage} from '../payrollPage'
import {chooseCompany,copy,emptyInput,inputValid,validUnits} from '../payrollUi'
import type {PayrollHomeData,BatchDetail,LineInput,PayProfile,PayBasis} from '../payrollTypes'
import {generationMode} from '../payGeneration'
import {hours} from '../time'
import CdacCalculationDetails from '../components/CdacCalculationDetails.vue'
import {useCdacText} from '../cdac'
import PayrollEvidence from '../components/PayrollEvidence.vue'
import PayItemFields from '../components/PayItemFields.vue'
import {WorkforceApiError} from '../api'
import type {ChangeWrite} from '../payChanges'
import PayChangeHandoff from '../components/PayChangeHandoff.vue'
import PhaseStatus from '../components/PhaseStatus.vue'
import {usePhaseText} from '../phaseText'
const handoff=ref<ChangeWrite|null>(null),sourceProfiles=ref<PayProfile[]>([])
const {english}=usePhaseText()
const route=useRoute(),router=useRouter(),id=String(route.params.id),employeeId=String(route.params.employeeId),{api,r,t,base,current,loading,busy,failure,notice,load,write}=usePayrollPage(),data=ref<BatchDetail|null>(null),basis=ref<PayBasis>('hourly'),mode=ref('manual'),cdacApplicable=ref(false),manualCdac=ref(false),cdacDraft=reactive({amount:'',note:''}),{d}=useCdacText(),draft=reactive<LineInput>(emptyInput(employeeId)),line=computed(()=>data.value?.calculation?.lines.find(l=>l.employeeId===employeeId)),editable=computed(()=>data.value&&['draft','calculated'].includes(data.value.batch.status)),needsSourceReview=computed(()=>!!line.value?.issues.includes('NO_SOURCES_REVIEW'))
onMounted(()=>void load(async()=>{const h=await api().get<PayrollHomeData>('/payroll-home');chooseCompany(h,'');const d=await api().get<BatchDetail>('/payroll-batches/'+id);chooseCompany(h,d.batch.companyId);if(!d.employees.some(e=>e.id===employeeId))throw new Error('not found');const current=d.calculation?.lines.find(l=>l.employeeId===employeeId)?.profile;const plans=current?[]:(await api().get<{items:PayProfile[]}>('/pay-profiles?companyId='+d.batch.companyId)).items;return {d,profile:current||plans.filter(p=>p.employeeId===employeeId&&p.effectiveFrom<=d.batch.month+'-31').sort((a,b)=>b.effectiveFrom.localeCompare(a.effectiveFrom))[0]}},v=>{data.value=v.d;sourceProfiles.value=v.profile?[v.profile]:[];Object.assign(draft,copy(v.d.inputs.find(i=>i.employeeId===employeeId)||emptyInput(employeeId)));basis.value=v.profile?.rule.basis||'hourly';mode.value=v.profile?generationMode(v.profile.rule):'manual';cdacApplicable.value=v.profile?.cdac?.status==='applicable';manualCdac.value=!!draft.cdacReview;if(draft.cdacReview)Object.assign(cdacDraft,draft.cdacReview)}))
function save(){if(manualCdac.value&&cdacApplicable.value&&(!/^\d{1,8}(\.\d{1,2})?$/.test(cdacDraft.amount)||!cdacDraft.note.trim())){failure.value=d('reviewInvalid');return}if(!editable.value||!inputValid(draft)||(mode.value==='manual'&&!validUnits(basis.value,draft))||(needsSourceReview.value&&(!draft.unitsReviewed||!draft.note.trim()))){failure.value=r('invalid');return}const body={expectedVersion:draft.version,workingDays:mode.value==='manual'?draft.workingDays||null:null,payableDays:mode.value==='manual'?draft.payableDays||null:null,unitsReviewed:mode.value==='manual'&&draft.unitsReviewed,specialDaysReviewed:draft.specialDaysReviewed,items:copy(draft.items),note:draft.note.trim(),cdacAutomatic:!cdacApplicable.value||!manualCdac.value,cdacReview:cdacApplicable.value&&manualCdac.value?{amount:cdacDraft.amount,note:cdacDraft.note.trim()}:null};void write(()=>api().put('/payroll-batches/'+id+'/inputs/'+employeeId,body),async()=>{if(current())await router.push(payrollReturn.value||base.value+'/payroll-batches/'+id)},e=>{if(!(e instanceof WorkforceApiError&&e.status===409&&e.code==='WORKFORCE_PAYROLL_APPROVAL_REQUIRED'))return false;handoff.value={expectedRevision:0,companyId:data.value!.batch.companyId,employeeId,effectiveDate:sourceProfiles.value[0]?.effectiveFrom||data.value!.batch.month+'-01',adoptionId:null,profile:null,derivedRule:null,months:[{month:data.value!.batch.month,input:copy(body)}],reason:''};return true})}
</script>
<template><section class="wf-panel wf-form-panel"><h2>{{r('lineInput')}}</h2><PhaseStatus :failure="failure" :notice="notice" :loading="loading"/><template v-if="data&&!loading"><RouterLink class="wf-button" :to="{path:base+'/pay-change-requests',query:{companyId:data.batch.companyId}}">{{english()?'Monthly pay change requests':'月度工资变更申请'}}</RouterLink><p>{{data.employees.find(e=>e.id===employeeId)?.name}} · {{data.batch.month}} · {{r(basis)}}</p><PayrollEvidence v-if="line" :line="line"/><dl v-if="line&&!line.hours" class="wf-details"><dt>{{r('work')}}</dt><dd>{{hours(line.workSeconds)}}</dd><dt>{{r('paidLeave')}}</dt><dd>{{hours(line.paidLeaveSeconds)}}</dd><dt>{{r('unpaidLeave')}}</dt><dd>{{hours(line.unpaidLeaveSeconds)}}</dd></dl><section v-if="mode!=='manual'" class="wf-section"><p class="wf-hint">{{r('generatedInput')}}</p><p v-if="mode==='fixed'">{{r('fixedSalaryHint')}}</p><p v-else-if="line">{{r('workingDays')}}: {{line.input.workingDays||'—'}} · {{r('payableDays')}}: {{line.input.payableDays||'—'}}</p></section><CdacCalculationDetails v-if="line?.cdacCalculation" :value="line.cdacCalculation"/><PayChangeHandoff v-if="handoff" :seed="handoff" :employees="data.employees" :profiles="sourceProfiles" :templates="[]" :birth-dates="{}" :pr-documents="{}" @cancel="handoff=null"/><form v-else-if="editable" @submit.prevent="save"><fieldset :disabled="busy"><template v-if="mode==='manual'&&basis!=='hourly'"><div class="wf-grid"><label v-if="basis==='monthly'">{{r('workingDays')}}<input v-model="draft.workingDays" data-field="workingDays" required inputmode="numeric"></label><label>{{r('payableDays')}}<input v-model="draft.payableDays" data-field="payableDays" required inputmode="decimal"></label></div><label class="wf-check"><input v-model="draft.unitsReviewed" type="checkbox" required>{{r('unitsReviewed')}}</label><p class="wf-hint">{{r('dayHint')}}</p></template><label v-if="mode==='manual'&&basis==='hourly'" class="wf-check"><input v-model="draft.unitsReviewed" type="checkbox" :required="needsSourceReview">{{r('hoursReviewed')}}</label><p v-if="needsSourceReview" class="wf-hint">{{r('noSourcesHint')}}</p><label class="wf-check"><input v-model="draft.specialDaysReviewed" type="checkbox">{{r('specialDaysReviewed')}}</label><p class="wf-hint">{{r('specialHint')}}</p><section v-if="cdacApplicable" class="wf-section"><h3>{{d('title')}}</h3><label class="wf-check"><input v-model="manualCdac" type="checkbox">{{d('override')}}</label><p class="wf-hint">{{d('reviewHint')}}</p><div v-if="manualCdac"><label>{{d('amount')}}<input v-model="cdacDraft.amount" required inputmode="decimal"></label><label>{{d('note')}}<textarea v-model="cdacDraft.note" required maxlength="500" rows="2"></textarea></label></div></section><h2>{{r('adjustments')}}</h2><PayItemFields :items="draft.items" :sources="line?.sources" :disabled="busy"/><label class="wf-section">{{r('note')}}<textarea v-model="draft.note" :required="needsSourceReview" maxlength="500" rows="3"></textarea></label></fieldset><p class="wf-hint">{{r('supportHint')}}</p><footer class="wf-form-actions"><RouterLink class="wf-button" :to="payrollReturn||base+'/payroll-batches/'+id">{{t('cancel')}}</RouterLink><button class="primary" :disabled="busy">{{busy?t('saving'):t('save')}}</button></footer></form><p v-else class="wf-hint">{{r('frozenHint')}}</p></template></section></template>
